def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(r.count(v) for r in grid))
    out = [row[:] for row in grid]

    # Find full-width or full-height separator lines of a single non-background color.
    for axis in (0, 1):
        n = h if axis == 0 else w
        m = w if axis == 0 else h
        lines = []
        for i in range(n):
            vals = [grid[i][j] for j in range(m)] if axis == 0 else [grid[j][i] for j in range(m)]
            if vals and len(set(vals)) == 1 and vals[0] != bg:
                lines.append(i)
        if not lines:
            continue
        # Treat the separator lines as boundaries and transfer the union of
        # the non-background marks across equal-sized neighboring regions.
        bounds = [-1] + lines + [n]
        regions = [(bounds[k] + 1, bounds[k+1]) for k in range(len(bounds)-1)]
        regions = [r for r in regions if r[1] > r[0]]
        sizes = [b-a for a,b in regions]
        if len(regions) < 2 or len(set(sizes)) != 1:
            continue
        length = sizes[0]
        for p in range(length):
            for q in range(m):
                vals = []
                for a,b in regions:
                    v = grid[a+p][q] if axis == 0 else grid[q][a+p]
                    if v != bg:
                        vals.append(v)
                if not vals:
                    continue
                v = vals[0]
                for a,b in regions:
                    if axis == 0:
                        if out[a+p][q] == bg:
                            out[a+p][q] = v
                    elif out[q][a+p] == bg:
                        out[q][a+p] = v
    return out
